function currentPlayerId(world) {
  for (const [id, ni] of world.query(NamedIdentity)) {
    if (String(ni?.identity || "") === "player") return id;
  }
  return 0;
}

function currentPriestId(world) {
  for (const [id, ni] of world.query(NamedIdentity)) {
    if (String(ni?.identity || "") === "townfolk_priest") return id;
  }
  return 0;
