function createQuestRift(ctx) {
  if (String(ctx.vars?.riftId || "")) return;
  const seed = ((ctx.world.seed >>> 0) ^ ((Number(ctx.bind.player || 0) * 0x9e3779b9) >>> 0) ^ 0x50524945) >>> 0;
